set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APPLY=0
for arg in "$@"; do if [[ "$arg" == "--apply" ]]; then APPLY=1; fi; done
[[ $APPLY -eq 1 ]] || { echo "Dry-run policy: rerun with --apply after review${DRY_RUN_NOTE:-}."; exit 0; }
[[ $EUID -eq 0 ]] || { echo "Run as root with sudo." >&2; exit 2; }

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
SOURCE="$ROOT/HYDRA-UMC-SWARM-SYNC"
TARGET=/opt/hydra-umc/swarm-sync
DEPLOY_CONTRACT=1
source "$HERE/deploy_lib.sh"
deploy_begin HYDRA-UMC-SWARM-SYNC "$TARGET"
SVC_USER="hydra-umc-swarm-sync"

[[ -f "$SOURCE/hydra-umc.project.json" ]] || { echo "HYDRA-UMC-SWARM-SYNC source is incomplete: $SOURCE" >&2; exit 2; }
[[ -f "$SOURCE/systemd/hydra-umc-swarm-sync.service" ]] || { echo "HYDRA-UMC-SWARM-SYNC has no unit hydra-umc-swarm-sync.service: $SOURCE" >&2; exit 2; }
if ! id -u "$SVC_USER" >/dev/null 2>&1; then
  useradd --system --home "$TARGET" --no-create-home --shell /usr/sbin/nologin "$SVC_USER"
fi
install -d -o root -g root -m 0755 "$TARGET"
HOOK="$HERE/build_hooks/swarm-sync.sh"
[[ -f "$HOOK" ]] || { echo "HYDRA-UMC-SWARM-SYNC needs its build hook build_hooks/swarm-sync.sh: $HOOK" >&2; exit 2; }
source "$HOOK"
install -d -o "$SVC_USER" -g "$SVC_USER" -m 0750 "$TARGET/data"
install -m 0644 "$SOURCE/systemd/hydra-umc-swarm-sync.service" /etc/systemd/system/hydra-umc-swarm-sync.service
install -m 0644 "$SOURCE/hydra-umc.project.json" "$TARGET/hydra-umc.project.json"
systemctl daemon-reload
deploy_finish HYDRA-UMC-SWARM-SYNC "$TARGET"
echo "swarm-sync installed. Enable manually after review: systemctl enable --now hydra-umc-swarm-sync"
if declare -F hook_after_install >/dev/null; then hook_after_install; fi
source "$HERE/service_registry.sh"
announce_health HYDRA-UMC-SWARM-SYNC
